  "scenario_id": "sc-2d248f",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [
        2015,
        2024
      ],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "Annual IP A/E swings between 0.413 and 1.654 while overall IP A/E is 0.9995. Approximate Poisson/sampling deviations: 2015 -595 claims (~-18.7 sigma), 2016 +746 (~+22 sigma), 2020 +946 (~+24 sigma), 2022 -460 (~-11 sigma), 2023 -386 (~-9 sigma). Annual A/E standard deviation is roughly 0.38 versus expected sampling volatility around 0.03-0.04.",
      "confidence": 0.97,
      "evidence": [
        "artifacts/ae_ip_by_year.csv rows 2015-2024 show A/E values 0.413, 1.654, 1.075, 0.931, 0.943, 1.612, 0.935, 0.740, 0.794, 0.965",
        "summary.json shows overall IP A/E 0.9995, indicating the large year-to-year swings offset and the level is not persistently shifted",
        "artifacts/ae_ip_termination.csv shows diagnosis termination A/E close to 1.0 (0.951-1.036), so a single-diagnosis recovery-rate change does not appear to be the primary driver"
      ],
      "recommended_action": "Treat as a probable data-quality or experience-aggregation anomaly until proven otherwise. Reconcile ip_claims.csv against exposure.csv and benchmarks/IP.csv; verify exposure definitions, policy/claim definition changes, claim counting rules, reporting lags, and expected claim calculations. Break experience out by diagnosis, duration month, claim start month, and distribution channel to locate offsetting shocks. If the volatility is confirmed in clean data, review IP volatility assumptions and pricing/valuation stresses, but avoid central assumption changes until root cause is established."
    }
  ]
}

